# Generated by build.py from recipe.yml for recipe ftp-resume-an-interrupted-upload. Do not edit.
Set-Location $PSScriptRoot
cmd /c 'mkdir site'
cmd /c 'mkdir other'
cmd /c 'head -c 200000 /dev/urandom > update.iso'
cmd /c 'head -c 65536 update.iso > site/first.iso'
cmd /c 'head -c 65536 update.iso > site/second.iso'
cmd /c 'head -c 65536 update.iso > site/third.iso'
cmd /c 'head -c 65536 update.iso > site/fourth.iso'
cmd /c 'head -c 65536 update.iso > site/offset.iso'
cmd /c 'head -c 65536 /dev/zero > site/zeros.iso'
cmd /c 'head -c 300000 /dev/zero > site/longer.iso'
cmd /c 'head -c 65536 update.iso > other/first.iso'
$server0 = Start-Process surl -ArgumentList '--allow-anonymous', '--allow-uploads', '--directory', 'site', 'ftp://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -sS -C - -T update.iso -w "%{size_upload}\n" ftp://127.0.0.1:8080/first.iso } finally { Stop-Process $server0 }
